<script>
function updateRplCount(){const all=document.querySelectorAll('.rpls-check');const checked=document.querySelectorAll('.rpls-check:checked');const el=document.getElementById('rplSelectedCount');if(el)el.textContent=checked.length+' MK aktif';}
function toggleRplCourses(state){document.querySelectorAll('.rpls-check').forEach(el=>el.checked=state);updateRplCount();}
document.querySelectorAll('.rpls-check').forEach(el=>el.addEventListener('change',updateRplCount));
</script>
